	{ L("established"),		EAP_TLS_ESTABLISHED		},
	{ L("fail"),			EAP_TLS_FAIL			},
	{ L("handled"),			EAP_TLS_HANDLED			},

	{ L("start"),			EAP_TLS_START_SEND		},
	{ L("request"),			EAP_TLS_RECORD_SEND		},
	{ L("ack"),			EAP_TLS_ACK_SEND		},

	{ L("first"),			EAP_TLS_RECORD_RECV_FIRST	},
