		type = Access-Request
	}
	recv Access-Request {
		eap
	}
	authenticate eap { eap }
}

server inner-tunnel {
	namespace = radius
	recv Access-Request {
		if (!outer.session-state.Filter-Id) {
			reject
		}
		if (outer.session-state.Filter-Id != User-Name) {
			reject
		}
		control.Password.Cleartext := "bob"
		pap
	}
	authenticate pap { pap }
}

server tls-session {
	namespace = tls
	verify certificate {
		map device_map "%{session-state.TLS-Certificate[0].Common-Name}" {
			session-state.Filter-Id := 'user'
		}
		if (!session-state.Filter-Id) {
			reject
		}
		ok
	}
}
EOF
