    attrs: dict[int, bytes] = {}
    offset = 20
    while offset + 2 <= len(packet):
        attr_type, length = packet[offset], packet[offset + 1]
        if length < 2 or offset + length > len(packet):
            break
        attrs[attr_type] = packet[offset + 2 : offset + length]
        offset += length
    return attrs


